-- Run after upgrade_auth.sql on an existing prachuap_directory database.
USE prachuap_directory;
CREATE TABLE IF NOT EXISTS loyalty_accounts (user_id BIGINT UNSIGNED PRIMARY KEY,points_balance INT UNSIGNED NOT NULL DEFAULT 0,lifetime_points INT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_loyalty_account_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS loyalty_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,review_id BIGINT UNSIGNED NOT NULL UNIQUE,event_type ENUM('review_approved','review_not_approved') NOT NULL,points INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_loyalty_events_user_created (user_id,created_at),CONSTRAINT fk_loyalty_event_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_loyalty_event_review FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE) ENGINE=InnoDB;
